'use strict';

const cors = require('cors');
const runner = require('../test-runner');

module.exports = function (app) {

  app.route('/_api/server-cli')
    .get(function (req, res) {
      console.log('requested');
      res.json({ status: 'ok' });
    });

  app.route('/_api/get-tests')
    .get(cors(), function(req, res) {
      console.log('requested');
      if(process.env.NODE_ENV === 'test') {
        console.log('sending tests info');
        res.json(getUserRunner(runner.tests));
      } else {
        res.json({ status: 'unavailable' });
      }
    });

  app.route('/_api/app-info')
  .get(function(req, res) {
    // Récupération compatible avec Node.js récent
    const headers = res.getHeaders ? res.getHeaders() : (res._headers || {});
    var hObj = {};
    Object.keys(headers).forEach(h => {
      if (!h.match(/^access-control-\w+/)) {
        hObj[h] = headers[h];
      }
    });
    delete hObj['strict-transport-security'];

    res.json({ headers: hObj });
  });

};

function getUserRunner(tests) {
  if (!tests) return [];
  var out = [];
  for (var i = 0; i < tests.length; i++) {
    var test = tests[i];
    var newTest = {
      title: test.title,
      suite: test.suite,
      state: test.state || test.states || 'passed',
      states: test.state || test.states || 'passed',
      body: test.body
    };
    out.push(newTest);
  }
  return out;
}